'use strict';

// MODULES //

var stride2offset = require( '@stdlib/strided/base/stride2offset' );
var base = require( './base.js' );


// MAIN //

/**
* Returns an updated sum of squares represented in scaled form.
*
* @param {NonNegativeInteger} N - number of indexed elements
* @param {Float64Array} X - input array
* @param {integer} strideX - stride length for `X`
* @param {Float64Array} scale - array containing a single element which specifies the scaling factor and is overwritten by the updated scaling factor
* @param {Float64Array} sumsq - array containing a single element which specifies the basic sum of squares from which output is factored out and is overwritten by the updated sum of squares
* @returns {void}
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var X = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var scale = new Float64Array( [ 1.0 ] );
* var sumsq = new Float64Array( [ 0.0 ] );
*
* dlassq( 4, X, 1, scale, sumsq );
* // scale => <Float64Array>[ 1.0 ]
* // sumsq => <Float64Array>[ 30.0 ]
*/
function dlassq( N, X, strideX, scale, sumsq ) {
	var ox;
	ox = stride2offset( N, strideX );
	base( N, X, strideX, ox, scale, 0, sumsq, 0 );
}


// EXPORTS //

module.exports = dlassq;
